  `season_year` char(5) COLLATE utf8mb4_general_ci NOT NULL,
  `number_round` int NOT NULL,
  `serious_revision` int NOT NULL DEFAULT '0',
  `team_number` int NOT NULL,
  `slot_number` int NOT NULL,
  `action_type` enum('assign','replace','remove','makeup','finish_refresh') COLLATE utf8mb4_general_ci NOT NULL,
  `old_player_identifier` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `new_player_identifier` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `old_player_points` int NOT NULL DEFAULT '0',
  `new_player_points` int NOT NULL DEFAULT '0',
  `note` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `updated_by` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `updated_ts` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`row_id`),
  KEY `idx_best_five_team_member_audit_round` (`season_year`,`number_round`,`serious_revision`),
  KEY `idx_best_five_team_member_audit_team_slot` (`team_number`,`slot_number`),
  KEY `idx_best_five_team_member_audit_action` (`action_type`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
